#include<iostream>
#include<cstdio>
#include<cstring>
#include<string>
#include<queue>
#include<map>
#include<set>
#include<cstdlib>
#include<vector>
#include<climits>
using namespace std;
typedef pair<int,int> pii;
const int MAX_N = 20;
const int MAX_NODES = 400;
const int MAX_EDGES = 200000;
const int INF = 199999999;

int grid[MAX_N][MAX_N];
int dist_from_source[MAX_NODES];
int bfs_queue[MAX_NODES];
int in_queue[MAX_NODES];
int graph[MAX_NODES][MAX_NODES];
int n, total_nodes, time_limit;
string row_input;
int source_r, source_c;
int dr[4] = {0, 0, -1, 1};
int dc[4] = {-1, 1, 0, 0};

struct Edge {
    int from, to, capacity, next;
} edges[MAX_EDGES];

int head[MAX_NODES], edge_count;
int source_node, sink_node;
vector<int> husks, reapers;

inline int pos(int r, int c) {
    return (r - 1) * n + c;
}

bool valid(int r, int c) {
    return r >= 1 && r <= n && c >= 1 && c <= n && grid[r][c] != -1;
}

void build_graph() {
    total_nodes = n * n;
    memset(graph, -1, sizeof(graph));
    for (int r = 1; r <= n; r++) {
        for (int c = 1; c <= n; c++) {
            if (grid[r][c] == -1) continue;
            int u = pos(r, c);
            graph[u][u] = 0;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (valid(nr, nc)) {
                    int v = pos(nr, nc);
                    graph[u][v] = 1;
                }
            }
        }
    }
}

void compute_shortest_from_source() {
    for (int i = 1; i <= total_nodes; i++) dist_from_source[i] = INF;
    int front = 0, rear = 0;
    int start = pos(source_r, source_c);
    dist_from_source[start] = 0;
    bfs_queue[rear++] = start;

    while (front < rear) {
        int cur = bfs_queue[front++];
        for (int nxt = 1; nxt <= total_nodes; nxt++) {
            if (graph[cur][nxt] == 1 && dist_from_source[nxt] > dist_from_source[cur] + 1) {
                dist_from_source[nxt] = dist_from_source[cur] + 1;
                bfs_queue[rear++] = nxt;
            }
        }
    }
}

void all_pairs_floyd() {
    for (int k = 1; k <= total_nodes; k++) {
        for (int i = 1; i <= total_nodes; i++) {
            for (int j = 1; j <= total_nodes; j++) {
                if (graph[i][k] != -1 && graph[k][j] != -1) {
                    if (graph[i][j] == -1 || graph[i][j] > graph[i][k] + graph[k][j]) {
                        graph[i][j] = graph[i][k] + graph[k][j];
                    }
                }
            }
        }
    }
}

void init_flow_graph() {
    memset(head, -1, sizeof(head));
    edge_count = 0;
    source_node = 0;
    sink_node = husks.size() + reapers.size() + 1;

    for (int i = 0; i < husks.size(); i++) {
        int id = i + 1;
        int cnt = husks[i * 3 + 2];
        edges[edge_count] = {source_node, id, cnt, head[source_node]};
        head[source_node] = edge_count++;
        edges[edge_count] = {id, source_node, 0, head[id]};
        head[id] = edge_count++;
    }

    for (int i = 0; i < reapers.size(); i++) {
        int id = husks.size() + i + 1;
        int cnt = reapers[i * 3 + 2];
        edges[edge_count] = {id, sink_node, cnt, head[id]};
        head[id] = edge_count++;
        edges[edge_count] = {sink_node, id, 0, head[sink_node]};
        head[sink_node] = edge_count++;
    }

    int src_pos = pos(source_r, source_c);
    for (int i = 0; i < husks.size(); i++) {
        int hr = husks[i * 3], hc = husks[i * 3 + 1], hcnt = husks[i * 3 + 2];
        int hp = pos(hr, hc);
        for (int j = 0; j < reapers.size(); j++) {
            int rr = reapers[j * 3], rc = reapers[j * 3 + 1], rcnt = reapers[j * 3 + 2];
            int rp = pos(rr, rc);
            if (graph[hp][rp] != -1 && graph[hp][rp] <= time_limit) {
                if (graph[hp][rp] < dist_from_source[rp]) {
                    edges[edge_count] = {i+1, husks.size()+j+1, INF, head[i+1]};
                    head[i+1] = edge_count++;
                    edges[edge_count] = {husks.size()+j+1, i+1, 0, head[husks.size()+j+1]};
                    head[husks.size()+j+1] = edge_count++;
                } else if (graph[hp][rp] == dist_from_source[rp]) {
                    for (int d = 0; d < 4; d++) {
                        int nrr = rr + dr[d], nrc = rc + dc[d];
                        if (valid(nrr, nrc)) {
                            int np = pos(nrr, nrc);
                            if (graph[hp][np] == graph[hp][rp] - 1 && graph[hp][np] < dist_from_source[np]) {
                                edges[edge_count] = {i+1, husks.size()+j+1, INF, head[i+1]};
                                head[i+1] = edge_count++;
                                edges[edge_count] = {husks.size()+j+1, i+1, 0, head[husks.size()+j+1]};
                                head[husks.size()+j+1] = edge_count++;
                            }
                        }
                    }
                }
            }
        }
    }
}

int level[MAX_NODES];
int queue_bfs[MAX_NODES];

bool bfs() {
    memset(level, -1, sizeof(level));
    int front = 0, rear = 0;
    queue_bfs[rear++] = source_node;
    level[source_node] = 0;

    while (front < rear) {
        int u = queue_bfs[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (level[v] == -1 && edges[e].capacity > 0) {
                level[v] = level[u] + 1;
                if (v == sink_node) return true;
                queue_bfs[rear++] = v;
            }
        }
    }
    return false;
}

int dfs(int u, int flow) {
    if (u == sink_node) return flow;
    for (int &e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        if (level[v] == level[u] + 1 && edges[e].capacity > 0) {
            int f = dfs(v, min(flow, edges[e].capacity));
            if (f > 0) {
                edges[e].capacity -= f;
                edges[e^1].capacity += f;
                return f;
            }
        }
    }
    return 0;
}

int max_flow() {
    int result = 0;
    while (bfs()) {
        memcpy(head, head, sizeof(head));
        while (int f = dfs(source_node, INF)) {
            result += f;
        }
    }
    return result;
}

int compute_solution() {
    grid[source_r][source_c] = 0;
    build_graph();
    compute_shortest_from_source();
    grid[source_r][source_c] = -1;
    build_graph();
    all_pairs_floyd();
    init_flow_graph();
    return max_flow();
}

int main() {
    cin >> n >> time_limit;
    husks.clear(); reapers.clear();
    memset(grid, 0, sizeof(grid));

    for (int i = 1; i <= n; i++) {
        cin >> row_input;
        for (int j = 0; j < n; j++) {
            if (row_input[j] == 'Y') grid[i][j+1] = -1;
            else if (row_input[j] == 'Z') {
                source_r = i; source_c = j+1;
                grid[i][j+1] = -1;
            }
            else if (row_input[j] > '0' && row_input[j] <= '9') {
                husks.push_back(i);
                husks.push_back(j+1);
                husks.push_back(row_input[j] - '0');
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        cin >> row_input;
        for (int j = 0; j < n; j++) {
            if (row_input[j] > '0' && row_input[j] <= '9') {
                reapers.push_back(i);
                reapers.push_back(j+1);
                reapers.push_back(row_input[j] - '0');
            }
        }
    }

    cout << compute_solution() << endl;
    return 0;
}
